            raise SystemExit('loai ' + t)
        if col:
            d['color'] = col
        ents.append(d)
    json.dump({'code': code, 'w': w, 'h': h, 'entities': ents, 'flags': []}, open(os.path.join(T, 'spec_%s.json' % code), 'w'))
    print(code, len(ents))
